package org.brightstats.desktop;
import java.nio.file.*;import java.util.*;import com.google.gson.*;import javafx.application.*;import javafx.scene.*;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.input.*;import javafx.scene.layout.*;import javafx.stage.Stage;import org.brightstats.data.*;import org.brightstats.stats.*;import org.brightstats.report.*;
public final class ExplorationUpgradeChecks extends Application {
 static Throwable failure;static int checks;static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 public void start(Stage stage){try{Path out=Path.of(getParameters().getRaw().getFirst());Files.createDirectories(out);UiAppearance.install(UserPreferences.defaults());double[][] data={{-2},{-1},{0},{1},{2}},before=Matrices.copy(data);var model=new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of(new SemModel.Parameter("Mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),0,1)));var fit=FimlSem.fit(data,model,FimlSem.Options.defaults());Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();JsonObject project=new JsonObject();project.addProperty("formatVersion",1);project.add("columnNames",gson.toJsonTree(List.of("Y")));project.add("observations",gson.toJsonTree(data));project.add("blocks",new JsonArray());project.add("edges",new JsonArray());JsonObject results=new JsonObject();results.add("fiml",gson.toJsonTree(fit));JsonObject report=ReportArchive.create("GAUSSIAN_OBSERVED_DATA_FIML",project,results,new JsonArray(),fit.warnings());JsonObject preserved=report.deepCopy();
  NumberAxis x=new NumberAxis(0,6,1),y=new NumberAxis(-3,3,1);LineChart<Number,Number> chart=new LineChart<>(x,y);chart.setAnimated(false);chart.setTitle("Observed values and fitted mean");x.setLabel("Source row");y.setLabel("Y");var a=new XYChart.Series<Number,Number>();a.setName("=Observed");var b=new XYChart.Series<Number,Number>();b.setName("Reference fit");for(int i=0;i<data.length;i++){a.getData().add(new XYChart.Data<>(i+1,data[i][0],GraphicPoint.analysis("Analysis row "+(i+1),i+1,List.of("Y"))));b.getData().add(new XYChart.Data<>(i+1,fit.estimates()[0]));}chart.getData().add(a);chart.getData().add(b);TableView<String[]> table=new TableView<>();TableColumn<String[],String> column=new TableColumn<>("Value");column.setCellValueFactory(v->new javafx.beans.property.ReadOnlyStringWrapper(v.getValue()[0]));table.getColumns().add(column);table.getItems().add(new String[]{"Complete source"});TabPane tabs=new TabPane(new Tab("Chart",chart),new Tab("Table",table));BorderPane root=new BorderPane(tabs,new Label("Synthetic mean model\nExact engine assumptions remain in the report."),null,null,null);ReportPresentation.decorate(root);ResultDashboard.install(root,report);stage.setScene(new Scene(root,1150,780));stage.show();root.applyCss();root.layout();
  var state=(ChartTools.State)chart.getProperties().get("brightstats.chartTools");require(state!=null,"Explorer installs on actual nested charts");require(ResultDashboard.metrics(report).stream().anyMatch(m->m.label().equals("Informative analysis rows")&&m.value().equals("5")),"Overview reads actual engine counts");require(ResultDashboard.metrics(report).stream().anyMatch(m->m.value().equals("Converged")),"Overview uses actual convergence state");require(ResultDashboard.metrics(report).stream().noneMatch(m->m.label().toLowerCase().contains("quality score")),"No invented scientific quality score");var dashboard=(ResultDashboard.Installed)root.getProperties().get("brightstats.dashboard");require(!dashboard.pane().isExpanded(),"Charts retain room by collapsing the overview");
  java.util.List<VisualSelection.Selection> selections=new ArrayList<>();root.addEventHandler(VisualSelection.TYPE,selections::add);Node mark=a.getData().getFirst().getNode();CanvasUpgradeChecks.mouse(mark,MouseEvent.MOUSE_CLICKED,2,2,false,false);require(selections.size()==1&&selections.getFirst().rows.equals(List.of(1))&&selections.getFirst().columns.equals(List.of("Y")),"Actual chart mark publishes explicit source binding");require(selections.getFirst().frame.equals(VisualSelection.frame(project)),"Source event identifies the complete source frame");JsonObject prepared=project.deepCopy();JsonObject prep=new JsonObject();prep.add("sourceRows",gson.toJsonTree(List.of(1,3,4,5,8)));prepared.add("dataPreparation",prep);VisualSelection.attach(root,prepared);VisualSelection.publish(mark,GraphicPoint.analysis("Second prepared row",2,List.of("Y")));require(selections.getLast().rows.equals(List.of(3)),"Prepared analysis row maps through explicit original-row identity");int count=selections.size();VisualSelection.publish(mark,GraphicPoint.analysis("Outside source",6,List.of("Y")));require(selections.size()==count,"Unmapped analysis IDs never select a guessed source row");VisualSelection.publish(mark,GraphicPoint.original("Deleted unit",List.of(3,8),List.of("Y")));require(selections.getLast().rows.equals(List.of(3,8)),"Whole-cluster source identities stay intact");VisualSelection.attach(root,project);JsonObject different=project.deepCopy();different.getAsJsonArray("observations").get(0).getAsJsonArray().set(0,new JsonPrimitive(-9));require(!VisualSelection.frame(project).equals(VisualSelection.frame(different)),"Different source values invalidate linking identity");
  ChartTools.zoom(x,.5,3);require(x.getLowerBound()==1.5&&x.getUpperBound()==4.5&&!x.isAutoRanging(),"Numeric zoom changes only displayed bounds");ChartTools.pan(x,new ChartTools.AxisState(false,1.5,4.5,.5),.25);require(x.getLowerBound()==2.25&&x.getUpperBound()==5.25,"Display pan preserves the plotted span");state.menu.getItems().getFirst().fire();require(x.getLowerBound()==0&&x.getUpperBound()==6&&x.getTickUnit()==1&&y.getLowerBound()==-3&&y.getUpperBound()==3,"Reset restores explicit axis presets");
  Label legend=(Label)chart.lookupAll(".chart-legend-item").stream().filter(n->n instanceof Label label&&label.getText().equals("Reference fit")).findFirst().orElseThrow();CanvasUpgradeChecks.mouse(legend,MouseEvent.MOUSE_CLICKED,5,5,false,false);root.layout();require(ChartTools.hidden(chart).equals(Set.of(1)),"Actual legend click toggles the matching series");require(b.getNode()!=null&&!b.getNode().isVisible(),"Series stays hidden through layout");String svg=SvgGraphics.charts(chart,"Exploration source identity");Files.writeString(out.resolve("hidden-series.svg"),svg);var factory=javax.xml.parsers.DocumentBuilderFactory.newInstance();factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);var xml=factory.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(svg.getBytes(java.nio.charset.StandardCharsets.UTF_8)));var metadata=JsonParser.parseString(xml.getElementsByTagName("metadata").item(0).getTextContent()).getAsJsonObject();require(metadata.getAsJsonArray("series").size()==2&&metadata.getAsJsonArray("series").get(1).getAsJsonObject().get("hidden").getAsBoolean(),"SVG retains complete source data plus visibility state");require(metadata.getAsJsonArray("series").get(0).getAsJsonObject().getAsJsonArray("points").get(0).getAsJsonObject().get("rowSpace").getAsString().equals("ANALYSIS"),"Vector export preserves explicit row-space metadata");require(xml.getElementsByTagName("path").getLength()==1,"SVG draws only the visible line");String tsv=ChartTools.tsv(chart);require(tsv.contains("'=Observed\tfalse")&&tsv.contains("\t-2.0\t"),"Copied plot data neutralizes formula labels without altering numeric signs");state.menu.getItems().get(1).fire();require(ChartTools.hidden(chart).isEmpty()&&b.getNode().isVisible(),"Show-all restores series visibility");
  NumberAxis tiny=new NumberAxis(1e-100,3e-100,1e-100);ChartTools.zoom(tiny,.5,2e-100);require(Math.abs(tiny.getLowerBound()/1e-100-1.5)<1e-12&&Math.abs(tiny.getUpperBound()/1e-100-2.5)<1e-12,"Zoom remains valid for small scientific units");require(report.equals(preserved)&&Arrays.deepEquals(data,before)&&a.getData().size()==5&&a.getData().getFirst().getYValue().doubleValue()==-2,"Exploration never changes data, estimator output or the archive");JsonArray tables=new JsonArray();var collect=Studio.class.getDeclaredMethod("collectReportTables",Node.class,String.class,JsonArray.class);collect.setAccessible(true);collect.invoke(null,root,"Analysis",tables);require(tables.size()==1,"Overview cards do not add fabricated tables to archived reports");root.applyCss();root.layout();GraphicExport.png(out.resolve("exploration.png"),root,1);
  TabPane diagnostics=ArchivedDiagnostics.create(report);require(diagnostics.getTabs().size()==2,"Archived FIML intervals and fitted covariance are directly available");root.setCenter(diagnostics);root.applyCss();root.layout();var interval=(LineChart<?,?>)((VBox)diagnostics.getTabs().getFirst().getContent()).getChildren().get(1);var term=fit.terms().getFirst();require(interval.getData().getFirst().getData().size()==3&&((Number)interval.getData().getFirst().getData().get(0).getXValue()).doubleValue()==term.lower()&&((Number)interval.getData().getFirst().getData().get(1).getXValue()).doubleValue()==term.estimate()&&((Number)interval.getData().getFirst().getData().get(2).getXValue()).doubleValue()==term.upper(),"Intervals use exact archived lower, estimate and upper values");diagnostics.getSelectionModel().selectLast();root.applyCss();root.layout();var heatmap=(MatrixHeatmap)((ScrollPane)diagnostics.getTabs().getLast().getContent()).getContent();require(heatmap.values[0][0]==fit.impliedCovariance()[0][0]&&heatmap.names.equals(List.of("Y")),"Heatmap uses explicitly mapped observed matrix names and values");selections.clear();heatmap.fireEvent(new KeyEvent(KeyEvent.KEY_PRESSED,"","",KeyCode.ENTER,false,false,false,false));require(selections.size()==1&&selections.getFirst().rows.isEmpty()&&selections.getFirst().columns.equals(List.of("Y")),"Heatmap keyboard selection links only actual matrix columns");String matrixSvg=SvgGraphics.charts(heatmap,"Matrix");require(matrixSvg.contains("bright-stats-matrix-graphic")&&matrixSvg.contains("1.0")&&matrixSvg.contains("Y × Y"),"Heatmap vector contains exact matrix metadata and full cell titles");Files.writeString(out.resolve("matrix.svg"),matrixSvg);GraphicExport.png(out.resolve("matrix.png"),heatmap,1);
  MatrixHeatmap signed=new MatrixHeatmap("Signed diagnostic",List.of("Observed X","Observed Y"),new double[][]{{1,-.8},{-.8,Double.NaN}});root.setCenter(signed);root.applyCss();root.layout();require(signed.color(-.8).getRed()>signed.color(-.8).getBlue(),"Negative cells have the opposing signed hue");String missingSvg=signed.svg();var missingXml=factory.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(missingSvg.getBytes(java.nio.charset.StandardCharsets.UTF_8)));var matrixMeta=JsonParser.parseString(missingXml.getElementsByTagName("metadata").item(0).getTextContent()).getAsJsonObject();require(matrixMeta.getAsJsonArray("matrix").get(1).getAsJsonArray().get(1).isJsonNull(),"Undefined archived matrix cells export as strict JSON null");for(double value:new double[]{-1,-.8,-.5,0,.3,.8,1}){double luminance=MatrixHeatmap.luminance(signed.color(value));double contrast=luminance<.179?1.05/(luminance+.05):(luminance+.05)/.05;require(contrast>=4.5,"Every matrix value label meets readable foreground contrast");}signed.fireEvent(new KeyEvent(KeyEvent.KEY_PRESSED,"","",KeyCode.RIGHT,false,false,false,false));require(signed.column==1&&signed.getAccessibleText().contains("Observed X × Observed Y"),"Heatmap arrows expose full variable identities and exact signed value");
  NumberAxis rx=new NumberAxis(20,100,20),ry=new NumberAxis(0,1,.2);UncertaintyChart ribbon=new UncertaintyChart(rx,ry);ribbon.setAnimated(false);for(int i=0;i<4;i++){var line=new XYChart.Series<Number,Number>();line.setName("Line "+i);line.getData().add(new XYChart.Data<>(20,.2));line.getData().add(new XYChart.Data<>(100,.7));ribbon.getData().add(line);}ChartTools.installChart(ribbon);ribbon.envelope(List.of(new double[]{20,.1,.4},new double[]{100,.6,.9}));root.setCenter(ribbon);root.applyCss();root.layout();require(ribbon.ribbon.getPoints().size()==8,"Uncertainty envelope renders both finite Wilson boundaries");String ribbonSvg=SvgGraphics.charts(ribbon,"Uncertainty");require(ribbonSvg.contains("bright-stats-uncertainty-ribbon")&&ribbonSvg.contains("wilsonLower95")&&ribbonSvg.contains("fill-opacity=\"0.19\""),"Vector uncertainty envelope preserves tested-N source bounds");((ChartTools.State)ribbon.getProperties().get("brightstats.chartTools")).toggle(1);require(!ribbon.ribbon.isVisible(),"Hidden bound hides corresponding envelope");require(report.equals(preserved)&&Arrays.deepEquals(data,before),"Diagnostic rendering leaves full archived numbers unchanged");JsonObject receipt=new JsonObject();receipt.addProperty("state","passed");receipt.addProperty("checks",checks);receipt.addProperty("numeric_archive_unchanged",true);Files.writeString(out.resolve("receipt.json"),receipt.toString());System.out.println(receipt);
 }catch(Throwable problem){failure=problem;problem.printStackTrace();}finally{stage.close();Platform.exit();}}
 public static void main(String[] args){launch(args);if(failure!=null)System.exit(1);}
}
